import * as T from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
export function releaseModel(root){const gs=new Set(),ms=new Set(),ts=new Set();root.traverse(o=>{if(o.geometry)gs.add(o.geometry);for(const m of (Array.isArray(o.material)?o.material:o.material?[o.material]:[])){ms.add(m);for(const v of Object.values(m))if(v?.isTexture)ts.add(v)}});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose());ts.forEach(t=>{t.image?.close?.();t.dispose()});root.removeFromParent()}
export async function loadStudioModel(asset,signal){const r=await fetch('/api/studio/assets/'+asset,{credentials:'same-origin',signal,cache:'no-store'});if(!r.ok)throw Error('模型加载失败，请重试');const bytes=await r.arrayBuffer();if(signal?.aborted)throw Error('已取消加载');const gltf=await new GLTFLoader().parseAsync(bytes,'');const root=gltf.scene;const box=new T.Box3().setFromObject(root),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3());if(![size.x,size.y,size.z].every(n=>Number.isFinite(n)&&n>.0001)){releaseModel(root);throw Error('模型尺寸无法识别')}const pivot=new T.Group();pivot.add(root);root.position.sub(new T.Vector3(center.x,box.min.y,center.z));pivot.userData.size=size;const seen=new Set();root.traverse(o=>{if(!o.isMesh)return;o.castShadow=o.receiveShadow=true;for(const m of(Array.isArray(o.material)?o.material:[o.material])){m.userData.baseColor=m.color?.clone();for(const t of Object.values(m))if(t?.isTexture&&!seen.has(t)){seen.add(t);const image=t.image;if(image?.width>2048||image?.height>2048){const c=document.createElement('canvas'),ratio=2048/Math.max(image.width,image.height);c.width=Math.round(image.width*ratio);c.height=Math.round(image.height*ratio);c.getContext('2d').drawImage(image,0,0,c.width,c.height);t.image=c;t.needsUpdate=true;image.close?.()}}}});return pivot}
export function createStudioModels(indoor){const root=new T.Group();root.userData.dynamic=true;indoor.add(root);const entries=new Map();let floor=0,disposed=false;
 function sync(objects){const ids=new Set(objects.map(x=>x.id));for(const [id,e]of entries)if(!ids.has(id)){e.abort.abort();if(e.model)releaseModel(e.model);entries.delete(id)}for(const o of objects){let e=entries.get(o.id);if(e&&e.asset!==o.asset){e.abort.abort();if(e.model)releaseModel(e.model);entries.delete(o.id);e=null}if(!e){e={asset:o.asset,abort:new AbortController(),spec:o};entries.set(o.id,e);document.dispatchEvent(new CustomEvent('studio-model-state',{detail:{id:o.id,state:'loading'}}));loadStudioModel(o.asset,e.abort.signal).then(model=>{if(disposed||entries.get(o.id)!==e){releaseModel(model);return}e.model=model;root.add(model);paint(e);document.dispatchEvent(new CustomEvent('studio-model-state',{detail:{id:o.id,state:'ready'}}))}).catch(err=>{if(!e.abort.signal.aborted)document.dispatchEvent(new CustomEvent('studio-model-state',{detail:{id:o.id,state:'failed',message:err.message}}))})}e.spec=o;if(e.model)paint(e)}}
 function paint(e){const o=e.spec,m=e.model,s=m.userData.size;m.position.set(o.x,o.floor*2.7,o.z);m.rotation.y=o.yaw;m.scale.set(o.width/s.x,o.height/s.y,o.depth/s.z);m.visible=floor===2||o.floor===floor;m.traverse(x=>{if(x.isMesh){x.userData.action=o.kind==='sofa'?'sit':o.kind==='seat'?'sit-ai-'+o.id:'design-open';for(const mat of(Array.isArray(x.material)?x.material:[x.material]))if(mat.color)mat.color.copy(mat.userData.baseColor).multiply(new T.Color(o.tint))}})}
 return {sync,show(f){floor=f;entries.forEach(e=>{if(e.model)paint(e)})},dispose(){disposed=true;for(const e of entries.values()){e.abort.abort();if(e.model)releaseModel(e.model)}entries.clear();root.removeFromParent()}};
}
